"""Cuaderno del estudiante, 4.º básico Lenguaje y Comunicación: OA 13 (clases «Narraciones con secuencia lógica»: situación y conflicto, causas, personajes y ambiente, desenlace, conectores).

Todos los relatos son originales y breves; cada ejercicio trae el texto que necesita.
"""
from __future__ import annotations

from student_content_le4_b import A, E, reg

OA13 = "LE04 OA 13"
MAT = "Este cuaderno, lápiz y los relatos escritos en los ejercicios. Sin materiales especiales."

# ================================================================ OA 13 · narraciones con secuencia lógica
reg(
    OA13, 1, MAT,
    "Aprenderé a planificar una narración: quién es el personaje, qué pasa al comienzo y cuál es el conflicto. Sirve para empezar un cuento con rumbo.",
    ["Sé que un cuento tiene inicio, desarrollo y final.", "Sé quiénes son los personajes."],
    ["Una narración cuenta lo que le pasa a un personaje. Antes de escribirla conviene planificar. El inicio presenta la situación inicial: quién es el personaje, dónde está y cuándo ocurre, cuando todo está en calma. Luego aparece el conflicto, que es el problema que rompe la calma y que el personaje debe resolver.",
     "Un buen plan responde cuatro preguntas: ¿Quién? (personaje). ¿Dónde y cuándo? (ambiente). ¿Qué quiere o necesita? (deseo). ¿Qué se lo impide? (conflicto). Por ejemplo: Rita vive junto al río (situación). Su barquito de papel se va con la corriente (conflicto). Quiere recuperarlo (deseo).",
     "El conflicto debe ser un problema que se pueda resolver con acciones. «Rita es feliz» no es un conflicto. «Rita pierde su barquito» sí lo es. Con un buen conflicto, el desarrollo sigue solo: el personaje intenta soluciones."],
    [("narración", "texto que cuenta lo que le pasa a un personaje"), ("situación inicial", "cómo está todo antes del problema"), ("conflicto", "problema que el personaje debe resolver"), ("personaje principal", "el protagonista de la historia")],
    [("Encontrar el conflicto", "«Rita vive junto al río. Una mañana, su barquito de papel se va con la corriente.» ¿Cuál es el conflicto?", ["Antes del problema, todo estaba tranquilo.", "El problema es que el barquito se va.", "Ese es el conflicto."], "El barquito de papel se va con la corriente"),
     ("Armar un plan", "Personaje: Tomás. Lugar: una playa. Deseo: llegar a la fiesta a tiempo. ¿Cuál puede ser el conflicto: A) Su bicicleta se pincha. B) Le gusta la playa.", ["Debe impedir que logre su deseo.", "Una bicicleta pinchada lo atrasa.", "B no impide nada."], "A")],
    [("Empezar contando muchas cosas sin un problema.", "Sin conflicto no hay historia.", "Incluye un problema que el personaje deba resolver."), ("Poner un conflicto imposible de resolver con acciones.", "No deja avanzar el relato.", "Elige un problema que el personaje pueda enfrentar.")],
    ([E("¿La situación inicial presenta al personaje y el lugar o el final del cuento?", "Al personaje y el lugar", "Es el comienzo."),
      E("¿El conflicto es el problema o el final feliz?", "El problema", "Rompe la calma inicial."),
      E("«Ana vive en un faro.» ¿Es situación inicial o conflicto?", "Situación inicial", "Solo presenta al personaje y el lugar.")],
     [E("«Una tormenta apagó la luz del faro.» ¿Es situación inicial o conflicto?", "Conflicto", "Es un problema para el personaje."),
      E("Plan: ¿Quién? Ana. ¿Dónde? En un faro. ¿Qué quiere? Que los barcos vean la luz. ¿Qué se lo impide? Se apagó la luz. ¿Cuál es el deseo?", "Que los barcos vean la luz", "Es lo que quiere lograr."),
      E("¿Para qué sirve planificar la narración antes de escribirla?", "Para saber quién, dónde, qué quiere y qué problema hay", "Da rumbo al cuento.")],
     [E("Sofía quiere ganar la carrera del colegio. ¿Cuál es un buen conflicto: A) Se le desata un zapato justo en la partida. B) Le gusta correr.", "A", "Le impide cumplir su deseo."),
      E("«Luna es una gata que duerme en el sol. Duerme y duerme.» ¿Hay conflicto? Responde sí o no.", "No", "No hay ningún problema."),
      E("«Pedro se da cuenta de que perdió la llave de su casa.» ¿Es conflicto o situación inicial?", "Conflicto", "Es un problema que debe resolver.")],
     [E("Cuento de Ema: «Ema vive en un pueblo. Hay una plaza. Hace sol. Todos son felices». ¿Qué le falta?", "Un conflicto", "No hay ningún problema que mueva la historia."),
      E("Rita quiere recuperar su barquito de papel, pero la corriente se lo lleva. ¿Cuál es el deseo y cuál es el conflicto? Responde en ese orden.", "Recuperar el barquito; la corriente se lo lleva", "El deseo es lo que quiere y el conflicto es lo que se lo impide.")],
     [E("Tres comienzos. A) «Pía vive en un nido en lo alto de un pino; una mañana el viento tira su nido al suelo.» B) «Pía es un pájaro lindo.» C) «Pía come semillas.» ¿Cuál presenta una situación inicial y un conflicto?", "A", "Tiene personaje, lugar y problema."),
      E("En el comienzo A de arriba, ¿cuál es el conflicto?", "El viento tira su nido al suelo", "Es el hecho que rompe la calma.")]),
    [E("Quieres escribir un cuento sobre un niño llamado Luis que debe entregar una carta a su profesora. ¿Cuál es un buen conflicto: A) La carta se cae a un charco. B) Luis tiene una carta.", "A", "Es un problema que lo obliga a actuar.")],
    [E("¿El conflicto es un problema?", "Sí", "Rompe la calma."),
     E("¿La situación inicial presenta al personaje?", "Sí", "Dice quién y dónde."),
     E("¿Un cuento sin conflicto tiene historia?", "No", "No hay nada que resolver.")],
    ("Planifica una narración con este molde. Elige un personaje (un niño, una gata o un robot) y completa: ¿Quién es? ¿Dónde y cuándo? ¿Qué quiere? ¿Cuál es el conflicto que se lo impide? Luego escribe el comienzo de tu cuento en tres oraciones (situación inicial y conflicto).", "Personaje: Ema, una gata. Lugar: tejado de una casa, de noche. Quiere: atrapar una luciérnaga. Conflicto: la luciérnaga se esconde en un agujero. Comienzo: Ema es una gata gris que vive en un tejado. Una noche vio una luciérnaga. Pero la luciérnaga se escondió en un agujero.", ["responde las cuatro preguntas del plan", "el conflicto impide el deseo", "el comienzo tiene situación inicial y conflicto", "tres oraciones"], ["plan y comienzo escritos"], ["no tener conflicto", "olvidar el deseo"], "Lee tu plan a otra persona y pregúntale si entendió el problema."),
    "Escribe un conflicto distinto para el personaje del plan que hiciste.",
    "Escribe tres comienzos distintos para un cuento sobre una mochila perdida.")

reg(
    OA13, 2, MAT,
    "Aprenderé a ordenar las acciones de una narración de modo que cada una tenga una causa. Sirve para que el relato se entienda y no parezca una lista de hechos sueltos.",
    ["Sé el inicio y el conflicto de un relato.", "Sé ordenar hechos en el tiempo."],
    ["Una secuencia lógica es el orden de los hechos de una narración, donde cada uno se entiende por el anterior. Una causa es lo que hace que algo ocurra y una consecuencia es lo que ocurre por eso. Si Rita pierde su barquito, corre por la orilla para alcanzarlo. La causa es la pérdida; la consecuencia, que corra.",
     "Algunos conectores de causa son: porque, ya que, como, por eso, así que, entonces. «Rita corrió porque el barquito se alejaba.» «El barquito se alejaba; por eso Rita corrió.» Los conectores de tiempo ordenan: primero, después, luego, más tarde, de pronto, finalmente.",
     "Para revisar una secuencia, pregunta tras cada acción: ¿por qué pasó? y ¿qué pasó después por eso? Si una acción no tiene relación con las demás, o aparece sin razón, la secuencia pierde lógica."],
    [("secuencia lógica", "orden de los hechos en que cada uno se explica por el anterior"), ("causa", "lo que hace que algo ocurra"), ("consecuencia", "lo que ocurre por una causa"), ("conector", "palabra que une ideas")],
    [("Ordenar por causa", "Ordena: A) Rita corrió por la orilla. B) El barquito se alejó. C) Rita alcanzó el barquito. D) Rita lo sacó del agua.", ["Primero el barquito se aleja (causa).", "Por eso corre y lo alcanza.", "Después lo saca."], "B, A, C, D"),
     ("Elegir el conector", "«Tomás llevó paraguas ______ el cielo estaba nublado.» ¿Porque o aunque?", ["El paraguas se lleva por una razón.", "Porque da la causa.", "Aunque da contraste."], "porque")],
    [("Poner acciones sin relación entre sí.", "El lector no entiende por qué pasan.", "Pregunta: ¿qué hecho causa el siguiente?"), ("Usar «y» para todo.", "No muestra la causa ni el orden.", "Usa porque, por eso, luego, después.")],
    ([E("¿La causa es lo que hace que algo ocurra o lo que ocurre después?", "Lo que hace que algo ocurra", "La consecuencia es lo que ocurre después."),
      E("«Llovió, por eso nos mojamos.» ¿Cuál es la causa: llovió o nos mojamos?", "Llovió", "Fue lo que originó lo otro."),
      E("¿«Porque» introduce una causa o una consecuencia?", "Una causa", "Explica la razón.")],
     [E("Ordena: A) Rita corrió. B) El barquito se alejó. ¿Cuál va primero?", "B", "La causa va antes."),
      E("«Pedro se fue temprano ______ tenía que llegar al colegio.» ¿Porque o aunque?", "Porque", "Da la razón."),
      E("«Hacía frío; ______ me puse el abrigo.» ¿Por eso o pero?", "Por eso", "Une la causa con la consecuencia.")],
     [E("Ordena: A) El gato saltó a la mesa. B) Escuchó un ruido. C) Vio un ratón. D) Corrió tras él. ¿Qué orden tiene la secuencia?", "B, C, A, D", "Primero el ruido, luego la vista, el salto y la persecución."),
      E("«La luz se apagó ______ no pudimos leer.» ¿Por eso o porque?", "Por eso", "La luz apagada causa que no puedan leer."),
      E("«No pudimos leer ______ la luz se apagó.» ¿Por eso o porque?", "Porque", "Da la causa después del hecho.")],
     [E("Texto: «Ema se cayó. Después fue a la plaza. Ema tenía una raspadura. Compró una pelota.» ¿Qué falla en la secuencia?", "Las acciones no se explican por la anterior", "No hay causa que las una."),
      E("«Tomás llevó el paraguas aunque el cielo estaba nublado.» ¿Qué conector cambiarías para mostrar causa?", "Cambiaría «aunque» por «porque»", "Porque da la razón.")],
     [E("Ordena la secuencia y escribe las letras: A) Ema pidió ayuda. B) Se le cayó el cuaderno al charco. C) Un compañero se lo secó con su chaleco. D) Salió del colegio. ¿Qué orden es el más lógico?", "D, B, A, C", "Sale, se le cae, pide ayuda y lo seca."),
      E("En la secuencia anterior, ¿cuál es la causa de que Ema pidiera ayuda?", "Se le cayó el cuaderno al charco", "Fue el problema que la hizo pedir ayuda.")]),
    [E("Estás escribiendo: «Mateo llegó tarde ______ perdió el bus.» ¿Qué conector usas: porque o aunque?", "Porque", "Da la causa de su atraso.")],
    [E("¿Una secuencia lógica explica cada hecho por el anterior?", "Sí", "Por eso se entiende."),
     E("¿«Por eso» introduce una consecuencia?", "Sí", "Une la causa con lo que ocurre."),
     E("¿Se puede cambiar el orden sin que se entienda?", "No", "El orden importa.")],
    ("Con estas acciones escribe un párrafo de cuatro oraciones con secuencia lógica y al menos dos conectores (por ejemplo porque, por eso, luego): Ema quiere regar una planta. La regadera está vacía. Ema llena la regadera en la llave. Riega la planta.", "Ema quería regar su planta, pero la regadera estaba vacía. Por eso fue a la llave. Luego llenó la regadera. Finalmente regó la planta.", ["incluye las cuatro acciones", "las ordena con lógica", "usa al menos dos conectores", "cada acción se explica por la anterior"], ["párrafo de cuatro oraciones"], ["mezclar el orden", "usar solo «y»"], "Lee tu párrafo a otra persona y pregúntale si el orden tiene sentido."),
    "Escribe dos oraciones unidas con «por eso».",
    "Escribe cuatro acciones desordenadas de un relato tuyo y pide a alguien que las ordene.")

reg(
    OA13, 3, MAT,
    "Aprenderé a mostrar cómo es un personaje y el ambiente con detalles y lenguaje expresivo. Sirve para que el lector imagine la historia.",
    ["Sé escribir con detalles de los sentidos.", "Sé qué es un personaje."],
    ["Un personaje se conoce por lo que hace, dice y piensa, y también por su aspecto. En lugar de escribir «Luis era generoso», puedes mostrarlo: «Luis partió su manzana y le dio la mitad a Ana». Así el lector lo descubre. El ambiente es el lugar, el momento y el clima donde ocurre la historia.",
     "Para describir con lenguaje expresivo usa adjetivos precisos (viejo, brillante, húmedo), comparaciones con «como» (corría como un conejo) y verbos que muestran movimiento (se arrastró, saltó). Las onomatopeyas imitan sonidos: ¡pum!, ¡chas!, ¡cri-cri!.",
     "Descripciones breves bastan. Una o dos oraciones del ambiente al comienzo de una escena sirven para ubicar al lector: «Era de noche y la casa crujía con el viento». No detengas la historia con demasiadas descripciones."],
    [("ambiente", "lugar, momento y clima donde ocurre la historia"), ("descripción", "texto que muestra cómo es algo o alguien"), ("comparación", "relación entre dos cosas con «como»"), ("lenguaje expresivo", "palabras que hacen sentir, ver u oír lo narrado")],
    [("Mostrar un rasgo", "Rasgo: Luis es generoso. ¿Cuál lo muestra mejor: A) «Luis era generoso.» B) «Luis partió su manzana y le dio la mitad a Ana.»", ["A solo lo dice.", "B lo muestra con una acción.", "B."], "B"),
     ("Identificar la comparación", "«Corría como un conejo.» ¿Qué palabra marca la comparación?", ["Busco la palabra que une dos cosas.", "Es «como».", "Compara correr con un conejo."], "como")],
    [("Decir «era valiente» sin mostrar nada que lo haga ver.", "El lector no lo imagina.", "Muestra una acción que lo revele."), ("Llenar el texto de descripciones.", "La historia se detiene.", "Describe con una o dos oraciones.")],
    ([E("¿El ambiente es el lugar y momento de la historia o el nombre del autor?", "El lugar y momento de la historia", "Incluye el clima."),
      E("«Era de noche y la casa crujía con el viento.» ¿Es descripción del ambiente o de un personaje?", "Del ambiente", "Dice el momento, el lugar y el clima."),
      E("¿La palabra «como» sirve para comparar?", "Sí", "Une dos cosas parecidas.")],
     [E("«Luis partió su manzana y le dio la mitad a Ana.» ¿Qué rasgo muestra: generoso o egoísta?", "Generoso", "Comparte lo suyo."),
      E("«Sus ojos brillaban como dos estrellas.» ¿Qué compara?", "Los ojos con estrellas", "Une dos cosas con «como»."),
      E("¿Qué imita la onomatopeya «¡pum!»: un sonido o un olor?", "Un sonido", "Las onomatopeyas imitan sonidos.")],
     [E("Elige la oración más expresiva: A) «Salió de la cueva.» B) «Se arrastró fuera de la cueva con el corazón latiendo como un tambor.»", "B", "Tiene un verbo preciso y una comparación."),
      E("«El anciano caminaba despacio, apoyado en un bastón torcido.» ¿Qué muestra: su aspecto o su estado de ánimo?", "Su aspecto", "Describe cómo se ve y camina."),
      E("Completa con una comparación: «Su voz era suave como ______.» ¿Cuál sirve: la seda o un camión?", "La seda", "Seda y suavidad se relacionan.")],
     [E("Ana escribió: «Pedro era muy valiente». ¿Qué le falta para mostrarlo?", "Una acción que lo muestre", "Mostrar es mejor que decir."),
      E("Un texto dice: «El bosque era oscuro y húmedo. Cruj, cruj, hacían las hojas.» ¿Cuál es la onomatopeya?", "Cruj, cruj", "Imita el sonido de las hojas.")],
     [E("Elige el ambiente más adecuado para un cuento de misterio: A) «Brillaba el sol y los niños jugaban.» B) «La niebla cubría el patio y una puerta chirriaba sola.»", "B", "Crea una atmósfera de misterio."),
      E("Lee: «Teo se tapó los oídos cuando el trueno retumbó como un tambor gigante.» ¿Cuál es la comparación?", "El trueno retumbó como un tambor gigante", "Usa la palabra «como» para comparar.")]),
    [E("Quieres mostrar que Valeria es muy ordenada. ¿Qué escribes: «Valeria era ordenada» o «Valeria alineó sus lápices por colores antes de empezar»?", "«Valeria alineó sus lápices por colores antes de empezar»", "Lo muestra con una acción.")],
    [E("¿Se puede mostrar cómo es un personaje con una acción?", "Sí", "Es mejor que solo decirlo."),
     E("¿Las comparaciones usan «como»?", "Sí", "Une dos cosas parecidas."),
     E("¿Hay que describir mucho?", "No", "Basta con pocas oraciones.")],
    ("Escribe una escena de cuatro oraciones: dos que describan el ambiente (lugar, momento o clima) con lenguaje expresivo (una comparación o una onomatopeya) y dos que muestren un rasgo de un personaje a través de lo que hace. Elige entre: un personaje curioso, valiente o generoso.", "La cueva era oscura como la noche. En el fondo se oía ¡plic, plic! Teo se agachó y acercó el oído a la pared. Después sacó su linterna y avanzó para descubrir qué sonaba.", ["describe el ambiente en dos oraciones", "usa una comparación u onomatopeya", "muestra un rasgo con acciones", "tiene cuatro oraciones"], ["escena de cuatro oraciones"], ["decir el rasgo sin mostrarlo", "olvidar el ambiente"], "Lee la escena y pregunta a otra persona qué rasgo cree que tiene el personaje."),
    "Escribe una comparación con «como» para describir una tormenta.",
    "Escribe una oración que muestre que un personaje está nervioso sin usar la palabra «nervioso».")

reg(
    OA13, 4, MAT,
    "Aprenderé a construir un desenlace que resuelve el conflicto y se entiende por lo que pasó antes. Sirve para terminar bien una narración.",
    ["Sé el inicio, el conflicto y la secuencia.", "Sé qué es una consecuencia."],
    ["El desenlace es el final de la narración. Resuelve el conflicto, ya sea porque el personaje lo logra, lo logra a medias o cambia por lo que vivió. Un desenlace coherente se entiende por lo que pasó antes. Si Rita corre y alcanza el barquito, el final puede ser: lo recupera.",
     "Un desenlace no coherente aparece de la nada. «De repente, el barquito volvió solo» no se relaciona con nada. Tampoco sirve un final que no habla del conflicto. Un buen final responde la pregunta del comienzo: ¿qué pasó con el problema?",
     "Algunos finales posibles: el personaje logra su deseo, no lo logra pero aprende algo, o encuentra una solución distinta. Puedes cerrar con una oración que diga lo que siente el personaje."],
    [("desenlace", "parte final que resuelve el conflicto"), ("coherente", "que se entiende por lo anterior y no se contradice"), ("resolver", "dar solución a un problema"), ("cierre", "oración final de un relato")],
    [("Elegir un desenlace coherente", "Inicio: el barquito de Rita se aleja. Desarrollo: Rita corre por la orilla y estira una rama larga hacia el agua. Desenlace: A) Rita lo alcanza y vuelve contenta. B) De pronto aparece un dinosaurio y todos van al cine.", ["El conflicto es recuperar el barquito.", "A responde el conflicto y se explica por la carrera.", "B no se relaciona."], "A"),
     ("Cerrar con un sentimiento", "Escribe una oración final para: Rita recuperó su barquito.", ["Digo cómo se sintió.", "Uso una oración corta.", "La escribo."], "Rita sonrió aliviada y abrazó su barquito.")],
    [("Un final que aparece de la nada (magia, sueño).", "No se explica por lo anterior.", "Haz que la solución salga de las acciones del personaje."), ("Terminar sin resolver el conflicto.", "El lector queda con dudas.", "Di qué pasó con el problema.")],
    ([E("¿El desenlace es el comienzo o el final del relato?", "El final", "Resuelve el conflicto."),
      E("¿Un desenlace debe resolver el conflicto?", "Sí", "Es su función."),
      E("¿Un final que aparece de la nada es coherente?", "No", "No se explica por lo anterior.")],
     [E("Inicio: Ema pierde su gorro. Desarrollo: lo busca en el patio y en la sala. Desenlace posible: A) Lo encuentra bajo una silla. B) Se va a la luna. ¿Cuál es coherente?", "A", "Se explica por la búsqueda."),
      E("¿Para qué sirve la oración de cierre: para decir qué siente el personaje o para cambiar el tema?", "Para decir qué siente el personaje", "Termina la historia con un sentimiento."),
      E("Un desenlace puede ser que el personaje no logre su deseo, pero aprenda algo. ¿Es posible esto? Responde sí o no.", "Sí", "También resuelve el conflicto de otra manera.")],
     [E("Conflicto: la luz del faro se apagó. Acciones: Ana subió la escalera, cambió la ampolleta. ¿Cuál es el desenlace coherente: A) La luz volvió a brillar y los barcos pasaron. B) Ana se convirtió en pájaro.", "A", "Se explica por lo que hizo Ana."),
      E("Conflicto: Tomás perdió la llave. Acciones: buscó en su mochila y en su pieza. Desenlace posible: «La encontró bajo su cama». ¿Es coherente?", "Sí", "Está dentro de lo que buscó."),
      E("Para cerrar «Tomás encontró la llave», ¿qué cierre sirve: A) «Tomás suspiró aliviado y abrió la puerta.» B) «Los pingüinos viven en el sur.»", "A", "Cierra la historia con un sentimiento y una acción coherente.")],
     [E("Un cuento: Rita pierde su barquito, lo busca y al final dice «Y vivieron felices». ¿Qué le falta al desenlace?", "Decir qué pasó con el barquito", "No resuelve el conflicto."),
      E("Ema dice que «de pronto el barquito volvió solo» es un buen final. ¿Qué problema tiene?", "No se explica por lo que hizo Rita", "Aparece sin causa.")],
     [E("Tres finales para «Luis perdió su gorro en el parque». A) «Entonces apareció un genio y lo arregló todo.» B) «Pidió ayuda a un guardia, que lo había guardado en su oficina.» C) «Luis tenía tres lápices.» ¿Cuál resuelve el conflicto con coherencia?", "B", "Se relaciona con el problema y con una acción de pedir ayuda."),
      E("¿Cuántos finales de los tres anteriores son incoherentes con el relato?", "2", "A y C no se explican por lo que hizo Luis.")]),
    [E("Tu cuento: Pía pierde su nido y lo reconstruye con ramas. ¿Qué final es coherente: «Pía vive en un nido nuevo y duerme tranquila» o «Pía se hace astronauta»?", "«Pía vive en un nido nuevo y duerme tranquila»", "Resuelve el problema del nido.")],
    [E("¿El desenlace resuelve el conflicto?", "Sí", "Es el final."),
     E("¿Un final mágico sin explicación es coherente?", "No", "Debe salir de lo anterior."),
     E("¿Puede cerrar con un sentimiento?", "Sí", "Ayuda a terminar bien.")],
    ("Lee el comienzo: «Valeria quiere llevar su pastel al cumpleaños de su amiga, pero se le cae al suelo.» Escribe un desenlace de tres oraciones: lo que Valeria hace para resolver el problema, cómo termina y qué siente. El final debe salir de sus acciones.", "Valeria pidió ayuda y juntos compraron otro pastel en la pastelería. Llegó a la fiesta a tiempo. Se sintió muy aliviada.", ["resuelve el conflicto", "se explica por las acciones", "dice qué siente", "tiene tres oraciones"], ["desenlace de tres oraciones"], ["final mágico", "no resolver el pastel"], "Lee tu desenlace a otra persona y pregúntale si coincide con el problema."),
    "Escribe dos desenlaces distintos para «Tomás perdió su gorro».",
    "Escribe un final donde el personaje no logra su deseo pero aprende algo.")

reg(
    OA13, 5, MAT,
    "Aprenderé a revisar los conectores y la secuencia de una narración. Sirve para que mi cuento se lea de corrido y se entienda.",
    ["Sé ordenar acciones con causa.", "Sé qué es un conector."],
    ["Revisar es leer el borrador para mejorarlo. En una narración conviene revisar dos cosas: los conectores y la secuencia. Los conectores de tiempo ordenan los hechos: primero, luego, después, más tarde, de pronto, mientras, finalmente. Los de causa explican: porque, por eso, así que. Los de contraste muestran un obstáculo: pero, aunque.",
     "Para revisar: lee en voz baja y pregúntate si cada hecho se entiende por el anterior. Si hay un salto, agrega un conector o un hecho que lo explique. Si dos oraciones están al revés, cámbialas de lugar. Si repites «y luego» muchas veces, cambia algunos conectores por otros.",
     "Después de un conector de tiempo al comienzo de la oración se pone coma: «Más tarde, se apagó la luz.» «Finalmente, llegamos.» También se usa la coma antes de «pero»: «Quería correr, pero estaba cansado.» Revisa esos detalles al final."],
    [("revisar", "leer de nuevo para mejorar un texto"), ("conector de tiempo", "palabra que ordena los hechos en el tiempo"), ("coherencia", "que todo el texto se entiende y no se contradice"), ("salto", "paso de un hecho a otro sin explicación")],
    [("Agregar un conector", "Texto: «Tomás se levantó. Tomás tomó desayuno. Tomás fue al colegio.» Mejóralo con conectores.", ["Las acciones son seguidas.", "Agrego primero, después, finalmente.", "Evito repetir el nombre."], "Primero, Tomás se levantó. Después tomó desayuno. Finalmente, fue al colegio."),
     ("Ordenar oraciones", "Ordena: A) Entonces la rescató. B) Una niña cayó al río. C) El perro la vio. ¿Qué orden es lógico?", ["Primero algo cae.", "Luego el perro lo ve.", "Después la rescata."], "B, C, A")],
    [("Repetir «y luego» siempre.", "El texto se vuelve monótono.", "Usa distintos conectores de tiempo."), ("Olvidar la coma después de «finalmente».", "Es un error de puntuación.", "Pon coma después de un conector de tiempo al inicio.")],
    ([E("¿«Primero» y «luego» son conectores de tiempo?", "Sí", "Ordenan los hechos en el tiempo."),
      E("¿«Porque» es un conector de causa?", "Sí", "Explica la razón."),
      E("¿Se pone coma después de «finalmente» al empezar una oración?", "Sí", "Es un conector de tiempo al inicio.")],
     [E("Ordena: A) Fue al colegio. B) Se levantó. C) Tomó desayuno. ¿Qué orden es lógico?", "B, C, A", "Primero se levanta, luego desayuna y al final va."),
      E("«Quería correr ______ estaba cansado.» ¿Pero o porque?", "Pero", "Muestra un obstáculo."),
      E("¿Cuál va con coma: «Finalmente llegamos» o «Finalmente, llegamos»?", "Finalmente, llegamos", "Hay coma después de un conector de tiempo al inicio.")],
     [E("Texto: «Ana abrió la puerta. ______ vio a su amiga.» ¿Qué conector va: «Entonces» o «Aunque»?", "Entonces", "Indica lo que ocurrió después."),
      E("Texto: «Luis estudió mucho. ______ sacó buena nota.» ¿Por eso o pero?", "Por eso", "Une causa y consecuencia."),
      E("Quieres decir que hubo un hecho inesperado. ¿Qué conector sirve: «de pronto» o «mientras»?", "De pronto", "Anuncia algo repentino.")],
     [E("Texto: «Rita llegó al río. Rita buscó el barquito. Rita lo vio. Rita lo recogió.» ¿Qué defecto tiene?", "Repite el nombre y no usa conectores", "Hay que variar y unir las oraciones."),
      E("Texto: «El perro ladró. Entonces el ladrón corrió. Porque el vecino llamó a la policía.» ¿Qué conector sobra o está mal usado?", "El «Porque» al inicio de la última oración", "Debería unirse a la oración anterior.")],
     [E("Revisa: «Primero, se apagó la luz. Todos gritaron. Después, la profesora encendió una vela. Finalmente todos se calmaron.» ¿Cuántos conectores de tiempo tiene?", "3", "Primero, después y finalmente."),
      E("Mismo texto. ¿A qué conector le falta la coma?", "Finalmente", "Debe decir «Finalmente, todos se calmaron».")]),
    [E("En tu cuento escribes: «Pedro cruzó el puente. Pedro vio un cocodrilo. Pedro corrió». ¿Qué mejorarías primero: agregar conectores y variar el sujeto, o cambiar el título?", "Agregar conectores y variar el sujeto", "Hace que se lea de corrido.")],
    [E("¿Se revisa para mejorar el texto?", "Sí", "Es leer de nuevo."),
     E("¿Hay que variar los conectores?", "Sí", "Así se evita repetir siempre lo mismo."),
     E("¿«Pero» muestra obstáculo?", "Sí", "Contrasta dos ideas.")],
    ("Revisa este borrador y reescríbelo en cuatro oraciones con conectores de tiempo y de causa, y con las comas necesarias: «Un niño vio un gato en el árbol. El gato lloraba. El niño llamó a un vecino. El vecino bajó al gato. El niño se puso feliz.» Mejora los saltos y evita repetir «el niño» y «el vecino».", "Un niño vio un gato en un árbol. Como el gato lloraba, llamó a un vecino. Luego, el vecino lo bajó con cuidado. Finalmente, el niño se puso feliz.", ["usa conectores de tiempo y de causa", "pone comas después de conectores al inicio", "evita repetir el sujeto", "mantiene la secuencia"], ["texto reescrito"], ["no variar los conectores", "olvidar las comas"], "Lee las dos versiones a otra persona y pregúntale cuál se entiende mejor."),
    "Escribe tres oraciones con «primero», «luego» y «finalmente».",
    "Reescribe un cuento tuyo antiguo agregando tres conectores.")
